Ext.define('DashletHTML.controller.StorageManager', {
    extend: 'Ext.Base',

    idsKey: 'idsStorage',
    gridKey: 'gridSelection',

    constructor: function(cfg) {
        var me = this,
            idsKey = me.idsKey,
            idsStorage = localStorage.getItem(idsKey),
            sesiones, filtros,
            data;

        if (cfg.ignoreLoad) return;

        me.ticket = cfg.ticket;
        me.controllerName = cfg.controllerName;

        if (idsStorage === null) {

            data = {
                filters: {},
                sessions: []
            };
        } else {
            data = JSON.parse(idsStorage);
        }

        sesiones = data.sessions;
        filtros = data.filters;


        if (sesiones.length === 0 || (sesiones[0] !== me.ticket)) {
            filtros = {};
        }

        sesiones = [me.ticket];

        filtros[me.ticket] = filtros[me.ticket] || {};
        var controlBean =  filtros[me.ticket][me.controllerName];

        if (controlBean === undefined) {

            filtros[me.ticket][me.controllerName] = {
                dims: {},
                gridSelection: []
            };
        }

        data = {
            filters: filtros,
            sessions: sesiones
        };

        localStorage.setItem("idsStorage", JSON.stringify(data));

    },

    saveFilter: function(dimension, subQuery, gridIndex) {
        var me = this,
            idsKey = me.idsKey,
            ticket = me.ticket,
            controllerName = me.controllerName,
            data = JSON.parse(localStorage.getItem(idsKey));

        data.filters[ticket][controllerName] = data.filters[ticket][controllerName] || {
            dims: {},
            gridSelection: []
        };

        data.filters[ticket][controllerName].dims[dimension] = subQuery;

        if (gridIndex) {
            data.filters[ticket][controllerName].gridSelection = gridIndex;
        }

        localStorage.setItem(idsKey, JSON.stringify(data));



    },

    getData: function() {

        var me = this,
            idsKey = me.idsKey,
            ticket = me.ticket,
            controllerName = me.controllerName,
            data = JSON.parse( localStorage.getItem(idsKey));

        return data.filters[ticket][controllerName];

    },

    setData: function(obj) {
        var me = this,
            idsKey = me.idsKey,
            ticket = me.ticket,
            controllerName = me.controllerName,
            data = JSON.parse( localStorage.getItem(idsKey)),
            info = data.filters[ticket][controllerName];

        data.filters[ticket][controllerName] = obj || info;

        localStorage.setItem(idsKey, JSON.stringify(data));
    },

    cleanDimension: function(dimension) {
        var me = this,
            ticket = me.ticket,
            controllerName = me.controllerName,
            data = JSON.parse(localStorage.getItem("idsStorage"));

        delete data.filters[ticket][controllerName].dims[dimension];

        /*if (gridIndex) {
                    data.filters[ticket][controllerName].gridSelection = gridIndex;
                }*/

        localStorage.setItem('idsStorage', JSON.stringify(data));


        return data.filters[ticket][controllerName];


    },

    getSavedQuery: function() {


        var me = this,
            idsKey = me.idsKey,
            tmp,
            strTmp,
            data = JSON.parse(localStorage.getItem(idsKey)),
            store,
            keys,
            k,
            item,
            finalReturn = [],
            query ;

        if (data === undefined) {
            return undefined;
        }

        tmp = data.filters[me.ticket];

        if (tmp === undefined) {
            return undefined;
        }
        store = tmp[me.controllerName].dims;

        if (store !== undefined) {
            keys = Object.keys(store);
            query = "";
            for (k in keys) {
                item = store[keys[k]];
                query += item.query;
            }
            strTmp = "<DimensionQueries xmlns='http://ns.ideasoft.biz/o3bi/schema/ViewQuery/2011-01'>" + query + "</DimensionQueries>";
            finalReturn.push( Base64.encode(strTmp) );
        }

        store = tmp[me.controllerName].params;

        if (store !== undefined && store.query !== undefined) {
            query+= store.query ;
            finalReturn.push(Base64.encode(store.query));
        }

        return {
            data: finalReturn,
            hasInfo: query !== undefined && query.trim().length > 0
        };

    },

    directAccess: function(sessionId, controlName) {
        var me = this,
            idsKey = me.idsKey,
            data = JSON.parse(localStorage.getItem(idsKey)),
            filters = data.filters[sessionId];

        return (filters && filters[controlName]) || {};


    },

    cleanGridSelection: function() {
        var me = this,
            ticket = me.ticket,
            controllerName = me.controllerName,
            data = JSON.parse(localStorage.getItem("idsStorage"));

        data.filters[ticket][controllerName].gridSelection = [];

        localStorage.setItem('idsStorage', JSON.stringify(data));
    }

});